const BLACK={r:0,g:0,b:0}, WHITE={r:1,g:1,b:1};
const GRAY900={r:0.1,g:0.1,b:0.1}, GRAY600={r:0.45,g:0.45,b:0.45};
const GRAY400={r:0.85,g:0.85,b:0.85}, GRAY200={r:0.96,g:0.96,b:0.96};
