const RED={r:0.82,g:0.11,b:0.09}, GREEN={r:0.11,g:0.45,b:0.14};

async function icon(key, size, color){
  const m = await figma.getNodeByIdAsync(ICON[key]);
  const inst = m.createInstance();
  inst.resize(size,size);
  function recolor(n){
    if ("fills" in n && n.fills && n.fills.length && n.fills[0].type==="SOLID"){ n.fills=[{type:"SOLID", color}]; }
    if ("strokes" in n && n.strokes && n.strokes.length && n.strokes[0].type==="SOLID"){ n.strokes=[{type:"SOLID", color}]; }
    if ("children" in n) n.children.forEach(recolor);
  }
  recolor(inst);
  return inst;
}

function T(text,{size=14,weight="Regular",color=GRAY900,align="LEFT",lh=null}={}){
  const t=figma.createText();
  t.fontName={family:"Inter", style:weight};
  t.characters=text;
  t.fontSize=size;
  t.fills=[{type:"SOLID",color}];
  t.textAlignHorizontal=align;
  if(lh) t.lineHeight={unit:"PIXELS", value:lh};
  t.textAutoResize="WIDTH_AND_HEIGHT";
  return t;
}

