function setStatusBarWhite(frame) {
  const sb = frame.children.find(c=>c.name==="Status Bar");
  if (sb) {
    // recursively recolor vector/text fills to white
    function recolor(n) {
      if (n.fills && n.fills.length && n.fills[0].type === "SOLID") {
        n.fills = [{type:"SOLID", color: WHITE}];
      }
      if ("children" in n) n.children.forEach(recolor);
    }
    recolor(sb);
  }
}
function setHomeIndicatorWhite(frame) {
  const hi = frame.children.find(c=>c.name==="Home Indicator");
  if (hi) {
    function recolor(n) {
      if (n.fills && n.fills.length && n.fills[0].type === "SOLID") {
        n.fills = [{type:"SOLID", color: WHITE}];
      }
      if ("children" in n) n.children.forEach(recolor);
    }
    recolor(hi);
  }
}

