const DARK_BG = {r:0.07,g:0.07,b:0.07};
const WHITE = {r:1,g:1,b:1};
const GRAY = {r:0.65,g:0.65,b:0.65};
const CARD_BG = {r:0.14,g:0.14,b:0.14};

function textNode(chars, size, weight, color, w) {
  const t = figma.createText();
  t.fontName = {family:"Inter", style:weight};
  t.fontSize = size;
  t.characters = chars;
  t.fills = [{type:"SOLID", color}];
  if (w) { t.resize(w, t.height); t.textAutoResize = "HEIGHT"; }
  return t;
}
function setWhite(frame, name) {
  const el = frame.children.find(c=>c.name===name);
  if (!el) return;
  function recolor(n) {
    if (n.fills && n.fills.length && n.fills[0].type === "SOLID") n.fills = [{type:"SOLID", color: WHITE}];
    if ("children" in n) n.children.forEach(recolor);
  }
  recolor(el);
}

async function setProgress(frame, x, y, step, total) {
  const comp = await figma.getNodeByIdAsync("6:213");
  const inst = comp.createInstance();
  inst.resize(327,4);
  inst.x = x; inst.y = y;
  frame.appendChild(inst);
  const segs = inst.children;
  for (let i=0;i<segs.length;i++) segs[i].fills=[{type:"SOLID", color: i<step ? WHITE : {r:0.3,g:0.3,b:0.3}}];
  return inst;
}

// Build an option row with avatar image, label, and radio icon
async function buildOptionRow(frame, x, y, w, avatarCompId, label, selected) {
  const row = figma.createFrame();
  row.name = "Option Row";
  row.resize(w, 72);
  row.x = x; row.y = y;
  row.fills = [{type:"SOLID", color: CARD_BG}];
  row.cornerRadius = 12;
  frame.appendChild(row);

  const avatarComp = await figma.getNodeByIdAsync(avatarCompId);
  const avatarInst = avatarComp.createInstance();
  avatarInst.resize(48,48);
  avatarInst.x = 12; avatarInst.y = 12;
  row.appendChild(avatarInst);

  const labelT = textNode(label, 16, "Medium", WHITE);
  labelT.x = 72; labelT.y = 26;
  row.appendChild(labelT);

  const radioComp = await figma.getNodeByIdAsync("1:169");
  const radioInst = radioComp.createInstance();
  radioInst.resize(24,24);
  radioInst.x = w-48; radioInst.y = 24;
  function recolor(n) {
    if (n.fills && n.fills.length && n.fills[0].type === "SOLID") n.fills = [{type:"SOLID", color: WHITE}];
    if ("children" in n) n.children.forEach(recolor);
  }
  recolor(radioInst);
  row.appendChild(radioInst);
  return row;
}

