function setWhite(frame, name) {
  const el = frame.children.find(c=>c.name===name);
  if (!el) return;
  function recolor(n) {
    if (n.fills && n.fills.length && n.fills[0].type === "SOLID") n.fills = [{type:"SOLID", color: WHITE}];
    if ("children" in n) n.children.forEach(recolor);
  }
  recolor(el);
}
