const out = [];
for (const id of ids) {
  const n = await figma.getNodeByIdAsync(id);
  function walk(node, depth) {
    return {name:node.name, type:node.type, x:node.x, y:node.y, w:node.width, h:node.height, chars: node.type==="TEXT"?node.characters:undefined, children: node.children && depth<2 ? node.children.map(c=>walk(c,depth+1)) : undefined};
  }
  out.push(walk(n,0));
}
return JSON.stringify(out,null,1);

