function addTabBar(frame, current) {
  const inst = tabBarComp.createInstance();
  inst.x = 0; inst.y = frame.height - 83;
  frame.appendChild(inst);
  const names = ["Home","Shop","Favorites","Bag","Profile"];
  for (const nm of names) {
    const grp = inst.findOne(n=>n.name===nm);
    const icon = grp.findOne(n=>n.name==="Icon");
    const label = grp.findOne(n=>n.name==="Label");
    const active = nm === current;
    const col = active ? BLACK : GRAY;
    label.fills = [{type:"SOLID", color: col}];
    if (icon.fills) icon.fills = [{type:"SOLID", color: col}];
    function recolor(n) {
      if (n.fills && n.fills.length && n.fills[0].type==="SOLID") n.fills=[{type:"SOLID", color: col}];
      if ("children" in n) n.children.forEach(recolor);
    }
    recolor(icon);
  }
  return inst;
}

