function productCard(frame, x, y, compName, status, name, type, price, extra) {
  const card = figma.createFrame();
  card.name = "ProductCard";
  card.x = x; card.y = y;
  card.resize(327, 112);
  card.fills = [];
  frame.appendChild(card);
  const imgFrame = figma.createFrame();
  imgFrame.name = "Image";
  imgFrame.resize(96,96);
  imgFrame.cornerRadius = 12;
  imgFrame.clipsContent = true;
  imgFrame.fills = [{type:"SOLID", color: LIGHTGRAY}];
  imgFrame.x = 0; imgFrame.y = 8;
  card.appendChild(imgFrame);
  const comp = mediaPage.findOne(n=>n.name===compName && n.type==="COMPONENT");
  const inst = comp.createInstance();
  const scl = Math.max(96/inst.width, 96/inst.height);
  inst.resize(inst.width*scl, inst.height*scl);
  inst.x = (96-inst.width)/2; inst.y = (96-inst.height)/2;
  imgFrame.appendChild(inst);

  let infoY = 8;
  if (status) {
    const statusColor = status==="Bestseller" ? {r:0,g:0.5,b:0.2} : RED;
    const st = textNode(status, 12, "Semi Bold", statusColor);
    st.x = 116; st.y = infoY;
    card.appendChild(st);
    infoY += 18;
  }
  const nm = textNode(name, 15, "Semi Bold", BLACK, 190);
  nm.x = 116; nm.y = infoY;
  card.appendChild(nm);
  infoY += nm.height + 2;
  const tp = textNode(type, 13, "Regular", GRAY, 190);
  tp.x = 116; tp.y = infoY;
  card.appendChild(tp);
  infoY += tp.height + 2;
  if (extra) {
    const ex = textNode(extra, 13, "Regular", GRAY, 190);
    ex.x = 116; ex.y = infoY;
    card.appendChild(ex);
    infoY += ex.height + 2;
  }
  const pr = textNode(price, 15, "Semi Bold", BLACK);
  pr.x = 116; pr.y = infoY + 4;
  card.appendChild(pr);

  const fav = iconFavComp.createInstance();
  fav.x = 303; fav.y = 8;
  card.appendChild(fav);
  return card;
}

