const ws = figma.root.children.find(p=>p.name.includes("Workspace"));
await figma.setCurrentPageAsync(ws);
const out = {};
for (const f of ws.children) {
  if (f.type !== "FRAME" || f.name.startsWith("·")) continue;
  const imgs = [];
  for (const n of f.findAll(()=>true)) {
    const fills = n.fills;
    if (Array.isArray(fills) && fills.some(x=>x.type==="IMAGE")) imgs.push(n.name);
  }
  out[f.name] = imgs.length + " imgs: " + [...new Set(imgs)].join(", ");
}
return JSON.stringify(out,null,1);

